"""Local UI server. NOT part of the official service (server.py is untouched and stays the graded API on :8000).

  python frontend/serve.py            # UI on http://127.0.0.1:8080, talks to the memory service on :8000

It serves the static page, proxies /api/<endpoint> to the memory service (so the browser has no CORS problem), and
exposes /view/memory, a read-only view of the SQLite file. That view works when the service runs on this machine with
the same MEMORY_DB (default: the system temp dir); with Docker the Memories page shows an empty state.
"""
import json
import os
import sqlite3
import sys
import urllib.error
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))
from backend.source.dal.repositories.memory_view import snapshot  # noqa: E402
from backend.source.utils import config  # noqa: E402

SERVICE = os.environ.get("MEMORY_URL", "http://localhost:8000").rstrip("/")
STATIC = {"/": ("index.html", "text/html; charset=utf-8"), "/app.js": ("app.js", "text/javascript; charset=utf-8"),
          "/app.css": ("app.css", "text/css; charset=utf-8")}
ENDPOINTS = {"health", "reset", "message", "answer", "act"}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, body: bytes, ctype="application/json; charset=utf-8"):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def _proxy(self, method: str):
        name = self.path.removeprefix("/api/")
        if name not in ENDPOINTS:
            return self._send(404, b'{"error":"unknown endpoint"}')
        data = self.rfile.read(int(self.headers.get("Content-Length") or 0)) if method == "POST" else None
        req = urllib.request.Request(f"{SERVICE}/{name}", data=data, method=method, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=120) as r:
                self._send(r.status, r.read())
        except urllib.error.HTTPError as e:
            self._send(e.code, e.read())
        except Exception as e:  # service down or unreachable: say so, never fake a result
            self._send(502, json.dumps({"error": f"memory service unreachable at {SERVICE}: {type(e).__name__}"}).encode())

    def do_GET(self):
        if self.path in STATIC:
            name, ctype = STATIC[self.path]
            return self._send(200, (HERE / name).read_bytes(), ctype)
        if self.path.startswith("/api/"):
            return self._proxy("GET")
        if self.path == "/view/memory":
            try:
                conn = sqlite3.connect(f"file:{config.db_path()}?mode=ro", uri=True)
                try:
                    out = snapshot(conn)
                finally:
                    conn.close()
            except sqlite3.Error:
                out = {"available": False, "now": "", "facts": [], "counts": {"sources": 0, "active": 0, "superseded": 0}, "forgets": []}
            return self._send(200, json.dumps(out, ensure_ascii=False).encode())
        self._send(404, b'{"error":"not found"}')

    def do_POST(self):
        if self.path.startswith("/api/"):
            return self._proxy("POST")
        self._send(404, b'{"error":"not found"}')


if __name__ == "__main__":
    port = int(os.environ.get("UI_PORT", "8080"))
    print(f"UI on http://127.0.0.1:{port}  (memory service {SERVICE}, db {config.db_path()})")
    ThreadingHTTPServer(("127.0.0.1", port), Handler).serve_forever()

