:root, :root[data-theme='dark'] {
  --bg:#1a1d26; --surface:#20242f; --raised:#272c39; --sunken:#161921; --line:#313748; --line-strong:#454d62;
  --text:#eceef3; --text-2:#c0c5d2; --muted:#8d94a7; --hl:#e9c46a; --hl-bg:rgba(233,196,106,.27); --hl-soft:rgba(233,196,106,.1);
