  --ink-button:#eceef3; --ink-button-text:#1a1d26; --scrim:rgba(10,12,18,.62);
  --shadow-pop:0 1px 0 rgba(255,255,255,.04) inset,0 18px 48px -12px rgba(0,0,0,.55); --focus:#f3d98f;
}
:root[data-theme='light'] {
  --bg:#f4f5f7; --surface:#fff; --raised:#fff; --sunken:#eceef2; --line:#dfe2e8; --line-strong:#c4c9d4;
  --text:#1b1e27; --text-2:#424858; --muted:#646b7e; --hl:#8a5f00; --hl-bg:rgba(246,201,72,.46); --hl-soft:rgba(246,201,72,.14);
  --forget:#a8354c; --forget-bg:rgba(168,53,76,.07); --forget-fill:#a8354c; --good:#2b7a4b; --planned:#3559a8;
  --ink-button:#1b1e27; --ink-button-text:#fff; --scrim:rgba(27,30,39,.38);
  --shadow-pop:0 1px 2px rgba(27,30,39,.06),0 20px 50px -18px rgba(27,30,39,.28); --focus:#8a5f00;
}
:root {
  --sans:'Geist Variable',ui-sans-serif,system-ui,'Segoe UI',sans-serif;
  --serif:'Newsreader Variable',Georgia,'Times New Roman',serif;
  --s-1:12.5px; --s0:13.5px; --s1:15px; --s2:17px; --s3:20px; --s5:32px;
  --r-control:8px; --r-panel:14px; --r-composer:18px; --header-h:60px; --ease:cubic-bezier(.2,.7,.2,1);
}
* { box-sizing:border-box; }
[hidden] { display:none !important; }
html, body { height:100%; margin:0; }
body { background:var(--bg); color:var(--text); font:var(--s0)/1.5 var(--sans); display:flex; flex-direction:column; }
button, input, textarea { font:inherit; color:inherit; }
button { cursor:pointer; }
:focus-visible { outline:2px solid var(--focus); outline-offset:2px; }
.grow { flex:1; }
.muted { color:var(--muted); }

.top { height:var(--header-h); display:flex; align-items:center; gap:16px; padding:0 24px; border-bottom:1px solid var(--line); background:var(--surface); flex:none; }
.mark { font:600 var(--s3)/1 var(--serif); letter-spacing:.14em; }
nav { display:flex; gap:4px; }
nav button, .ghost { background:none; border:1px solid transparent; border-radius:var(--r-control); padding:6px 12px; color:var(--text-2); }
nav button:hover, .ghost:hover { background:var(--raised); }
nav button.on { color:var(--text); border-color:var(--line-strong); background:var(--raised); }
.conn { font-size:var(--s-1); color:var(--muted); }
.conn::before { content:''; display:inline-block; width:8px; height:8px; border-radius:50%; background:var(--muted); margin-right:6px; }
.conn.ok::before { background:var(--good); } .conn.bad::before { background:var(--forget-fill); }

.page { flex:1; min-height:0; display:flex; flex-direction:column; }
.page.wide { max-width:1180px; width:100%; margin:0 auto; padding:28px 32px; overflow:auto; display:block; }
.transcript { flex:1; overflow:auto; padding:28px 24px 12px; }
.transcript > * { max-width:1040px; margin:0 auto 26px; }
.welcome { padding-top:8vh; max-width:620px !important; }
.welcome h1 { font:500 var(--s5)/1.2 var(--serif); margin:0 0 12px; }
.welcome p { color:var(--text-2); font-size:var(--s1); }

.msg.user { display:flex; justify-content:flex-end; }
.msg.user .bubble { max-width:min(560px,88%); padding:10px 16px; background:var(--raised); border:1px solid var(--line); border-radius:16px 16px 4px 16px; font:var(--s2)/1.5 var(--serif); white-space:pre-wrap; }
.msg.user .tag { display:block; font:var(--s-1) var(--sans); color:var(--muted); margin-top:4px; }
.msg.bot .bubble { max-width:680px; font:var(--s2)/1.6 var(--serif); white-space:pre-wrap; padding:2px 0 2px 14px; border-left:2px solid var(--hl); cursor:pointer; }
.msg.bot.abstain .bubble { border-left:2px dashed var(--line-strong); color:var(--text-2); }
.msg.bot.error .bubble { border-left-color:var(--forget-fill); cursor:default; }
.msg.bot .meta { margin:6px 0 0 14px; font-size:var(--s-1); color:var(--muted); }
.msg.bot .meta button { margin-left:10px; }
.msg.note .bubble { font-size:var(--s-1); color:var(--muted); }
.dots::after { content:'…'; animation:blink 1s steps(3) infinite; } @keyframes blink { 50% { opacity:.2; } }

.composer { flex:none; width:100%; max-width:1088px; margin:0 auto; padding:8px 24px 18px; }
.modes { display:flex; gap:6px; margin-bottom:8px; }
.modes label { border:1px solid var(--line); border-radius:var(--r-control); padding:4px 12px; color:var(--text-2); cursor:pointer; }
.modes label:has(input:checked) { background:var(--hl-soft); border-color:var(--hl); color:var(--text); }
.modes input { position:absolute; opacity:0; pointer-events:none; }
