.box textarea { flex:1; background:none; border:0; resize:none; outline:0; font:var(--s2)/1.5 var(--serif); max-height:30vh; }
.ink { background:var(--ink-button); color:var(--ink-button-text); border:0; border-radius:var(--r-control); padding:8px 18px; font-weight:600; }
.ink:disabled { opacity:.5; cursor:default; }
.danger { background:var(--forget-bg); color:var(--forget); border:1px solid var(--forget); border-radius:var(--r-control); padding:8px 16px; }

.bar { display:flex; align-items:center; gap:14px; flex-wrap:wrap; margin-bottom:18px; }
h2 { font:500 var(--s3)/1.2 var(--serif); margin:0; } h3 { font:500 var(--s2)/1.2 var(--serif); margin:32px 0 4px; }
.chips { display:flex; gap:4px; } .chips button { background:none; border:1px solid var(--line); border-radius:99px; padding:3px 12px; color:var(--text-2); }
.chips button.on { background:var(--hl-soft); border-color:var(--hl); color:var(--text); }
.card { background:var(--surface); border:1px solid var(--line); border-radius:var(--r-panel); padding:14px 16px; margin-bottom:10px; }
.card.old { background:var(--sunken); }
.card .head { display:flex; gap:10px; align-items:baseline; flex-wrap:wrap; }
.card .val { font:var(--s2)/1.4 var(--serif); }
.card .quote { margin-top:6px; color:var(--text-2); font:italic var(--s1)/1.5 var(--serif); }
.badge { font-size:var(--s-1); border:1px solid var(--line-strong); border-radius:99px; padding:0 8px; color:var(--muted); }
.badge.other { color:var(--planned); border-color:var(--planned); } .badge.history { color:var(--hl); border-color:var(--hl); }
.badge.good { color:var(--good); border-color:var(--good); } .badge.bad { color:var(--forget); border-color:var(--forget); }
.empty, .errbox { border:1px dashed var(--line-strong); border-radius:var(--r-panel); padding:24px; color:var(--muted); }
.errbox { color:var(--forget); border-color:var(--forget); background:var(--forget-bg); }
.sys { display:grid; grid-template-columns:max-content 1fr; gap:8px 24px; margin:18px 0; } .sys dt { color:var(--muted); } .sys dd { margin:0; word-break:break-all; }

.drawer { position:fixed; top:0; right:0; bottom:0; width:min(480px,100%); background:var(--surface); border-left:1px solid var(--line); box-shadow:var(--shadow-pop); z-index:20; overflow:auto; padding:20px; }
