.step { font:var(--s-1) ui-monospace,Consolas,monospace; color:var(--text-2); margin-bottom:4px; word-break:break-word; }
.scrim { position:fixed; inset:0; background:var(--scrim); z-index:10; }
dialog { background:var(--surface); color:var(--text); border:1px solid var(--line-strong); border-radius:var(--r-panel); box-shadow:var(--shadow-pop); padding:24px; max-width:440px; }
dialog::backdrop { background:var(--scrim); } dialog .row { display:flex; gap:8px; justify-content:flex-end; margin-top:16px; }

@media (max-width:900px) { .top { padding:0 12px; gap:8px; } .page.wide { padding:20px 16px; } }
@media (max-width:720px) { .mark { display:none; } .transcript { padding:20px 14px 8px; } .composer { padding:8px 14px 14px; } .box textarea { font-size:var(--s1); } }
@media (prefers-reduced-motion:reduce) { * { animation:none !important; transition:none !important; } }

