// HUSH UI: real calls only. /api/* is proxied to the memory service; /view/memory is a read-only look at its store.
const $ = (id) => document.getElementById(id);
const el = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; };
const store = { get(k) { try { return localStorage.getItem(k); } catch { return null; } }, set(k, v) { try { localStorage.setItem(k, v); } catch { /* private mode */ } } };

async function api(name, body) {
  const r = await fetch('/api/' + name, body === undefined ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const text = await r.text();
  let data = {}; try { data = JSON.parse(text); } catch { /* keep {} */ }
  if (!r.ok) throw new Error(data.error || `HTTP ${r.status}`);
  return data;
}
const view = async () => (await fetch('/view/memory')).json();
const nowIso = () => { const d = new Date(), p = (n) => String(n).padStart(2, '0'), o = -d.getTimezoneOffset(), a = Math.abs(o);
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}${o < 0 ? '-' : '+'}${p(Math.floor(a / 60))}:${p(a % 60)}`; };
let seq = 0; const newId = () => `ui${Date.now().toString(36)}${++seq}`;

// ---- theme, navigation, connection -----------------------------------------------------------
document.documentElement.dataset.theme = store.get('theme') || 'dark';
$('theme').onclick = () => { const t = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'; document.documentElement.dataset.theme = t; store.set('theme', t); };
function show(page) {
  document.querySelectorAll('.page').forEach((p) => { p.hidden = p.id !== 'page-' + page; });
  document.querySelectorAll('#nav button').forEach((b) => b.classList.toggle('on', b.dataset.page === page));
  if (page === 'memories') loadMemories(); if (page === 'system') loadSystem();
}
$('nav').onclick = (e) => e.target.dataset.page && show(e.target.dataset.page);
async function ping() {
  try { await api('health'); $('conn').textContent = 'service connected'; $('conn').className = 'conn ok'; return true; }
  catch (e) { $('conn').textContent = 'service unreachable'; $('conn').className = 'conn bad'; return false; }
}
ping(); setInterval(ping, 15000);

// ---- chat ------------------------------------------------------------------------------------
const MODE_HINT = { say: 'Tell the assistant something to remember…', ask: 'Ask what the assistant knows…', act: 'Give the assistant a job to do…' };
const mode = () => document.querySelector('input[name=mode]:checked').value;
document.querySelectorAll('input[name=mode]').forEach((r) => r.onchange = () => { $('input').placeholder = MODE_HINT[mode()]; $('world-row').hidden = mode() !== 'act'; });
$('input').addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); $('composer').requestSubmit(); } });

function add(node) { $('welcome').hidden = true; $('transcript').appendChild(node); node.scrollIntoView({ block: 'end' }); return node; }
function userBubble(text, tag) { const m = el('div', 'msg user'), b = el('div', 'bubble', text); if (tag) b.appendChild(el('span', 'tag', tag)); m.appendChild(b); return add(m); }

async function run(m, text, node) {   // node: the assistant bubble, filled in place so Retry can reuse it
  node.className = 'msg bot'; node.replaceChildren(el('div', 'bubble dots', 'Working'));
  try {
    if (m === 'say') {
      const before = await view();
      await api('message', { message: { id: newId(), ts: nowIso(), type: 'chat', turns: [{ role: 'user', content: text }] } });
      const after = await view();
      node.className = 'msg bot note';
      node.replaceChildren(el('div', 'bubble', after.available
        ? `Sent. Memory now holds ${after.counts.active} current and ${after.counts.superseded} earlier fact(s) (${after.counts.active - before.counts.active >= 0 ? '+' : ''}${after.counts.active - before.counts.active} current). See the Memories page for what was stored.`
        : 'Sent. The memory view is unavailable here, so I cannot show what was stored.'));
    } else if (m === 'ask') {
      const out = await api('answer', { question: text });
      const abstain = !out.evidence.length;
      node.className = 'msg bot' + (abstain ? ' abstain' : '');
      const b = el('div', 'bubble', out.answer || '(empty answer)'); b.onclick = () => openAnswer(text, out);
      node.replaceChildren(b, el('div', 'meta', abstain ? 'No supporting memory. Click for details.' : `${out.evidence.length} source(s). Click the answer to inspect.`));
    } else {
      const world = $('world').value.trim();
      const out = await api('act', { request: text, mcp_url: world.replace(/\/tools$/, '/mcp'), tools_url: world });
      const b = el('div', 'bubble', out.reply || '(no reply)'); b.onclick = () => openAct(text, out);
      node.replaceChildren(b, el('div', 'meta', `${out.trace.filter((t) => t.step === 'tool').length} tool call(s). Click the reply to inspect.`));
    }
  } catch (e) {
    node.className = 'msg bot error';
    const retry = el('button', 'ghost', 'Retry'); retry.onclick = () => run(m, text, node);
    const meta = el('div', 'meta', ''); meta.append('Could not complete this. ', retry);
    node.replaceChildren(el('div', 'bubble', e.message), meta);
  }
}
$('composer').onsubmit = async (e) => {
  e.preventDefault();
  const text = $('input').value.trim(), m = mode(); if (!text) return;
  $('input').value = ''; $('send').disabled = true;
  userBubble(text, { say: 'told', ask: 'asked', act: 'job' }[m]);
  await run(m, text, add(el('div', 'msg bot')));
  $('send').disabled = false; $('input').focus();
};

// ---- evidence drawer -------------------------------------------------------------------------
function drawer(title, build) { $('drawer-title').textContent = title; const b = $('drawer-body'); b.replaceChildren(); build(b); $('drawer').hidden = $('scrim').hidden = false; $('close').focus(); }
const closeDrawer = () => { $('drawer').hidden = $('scrim').hidden = true; };
$('close').onclick = $('scrim').onclick = closeDrawer;
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeDrawer(); });
const steps = (b, trace) => { b.appendChild(el('h4', null, 'How it was found')); (trace || []).forEach((t) => b.appendChild(el('div', 'step', JSON.stringify(t)))); };
function openAnswer(q, out) {
  drawer('Answer details', (b) => {
    b.appendChild(el('h4', null, 'Question')); b.appendChild(el('div', null, q));
    b.appendChild(el('h4', null, out.evidence.length ? 'Evidence used' : 'Abstained'));
    if (!out.evidence.length) b.appendChild(el('div', 'muted', 'Nothing stored supports an answer, so none was given.'));
    out.evidence.forEach((ev) => { const d = el('div', 'ev', ev.text); d.appendChild(el('small', null, 'message ' + ev.message_id)); b.appendChild(d); });
    steps(b, out.trace);
  });
}
function openAct(q, out) {
  drawer('Job details', (b) => {
    b.appendChild(el('h4', null, 'Request')); b.appendChild(el('div', null, q));
    b.appendChild(el('h4', null, 'Steps taken')); out.trace.filter((t) => t.step === 'tool').forEach((t) => b.appendChild(el('div', 'step', `${t.name} ${t.args} → ${t.result}`)));
    if (!out.trace.some((t) => t.step === 'tool')) b.appendChild(el('div', 'muted', 'No tools were called.'));
