/* Marginalia tokens, taken from the approved design reference (engineering_reference ch. 14). */
:root, :root[data-theme='dark'] {
  --bg:#1a1d26; --surface:#20242f; --raised:#272c39; --sunken:#161921; --line:#313748; --line-strong:#454d62;
  --text:#eceef3; --text-2:#c0c5d2; --muted:#8d94a7; --hl:#e9c46a; --hl-bg:rgba(233,196,106,.27); --hl-soft:rgba(233,196,106,.1);
  --forget:#e8949f; --forget-bg:rgba(232,148,159,.12); --forget-fill:#c9566a; --good:#8fcfa6; --planned:#9db8ee;
  --ink-button:#eceef3; --ink-button-text:#1a1d26; --scrim:rgba(10,12,18,.62);
  --shadow-pop:0 1px 0 rgba(255,255,255,.04) inset,0 18px 48px -12px rgba(0,0,0,.55); --focus:#f3d98f;
}
:root[data-theme='light'] {
  --bg:#f4f5f7; --surface:#fff; --raised:#fff; --sunken:#eceef2; --line:#dfe2e8; --line-strong:#c4c9d4;
  --text:#1b1e27; --text-2:#424858; --muted:#646b7e; --hl:#8a5f00; --hl-bg:rgba(246,201,72,.46); --hl-soft:rgba(246,201,72,.14);
  --forget:#a8354c; --forget-bg:rgba(168,53,76,.07); --forget-fill:#a8354c; --good:#2b7a4b; --planned:#3559a8;
  --ink-button:#1b1e27; --ink-button-text:#fff; --scrim:rgba(27,30,39,.38);
  --shadow-pop:0 1px 2px rgba(27,30,39,.06),0 20px 50px -18px rgba(27,30,39,.28); --focus:#8a5f00;
}
:root {
  --sans:'Geist Variable',ui-sans-serif,system-ui,'Segoe UI',sans-serif;
  --serif:'Newsreader Variable',Georgia,'Times New Roman',serif;
  --s-1:12.5px; --s0:13.5px; --s1:15px; --s2:17px; --s3:20px; --s5:32px;
  --r-control:8px; --r-panel:14px; --r-composer:18px; --header-h:60px; --ease:cubic-bezier(.2,.7,.2,1);
}
* { box-sizing:border-box; }
[hidden] { display:none !important; }
html, body { height:100%; margin:0; }
body { background:var(--bg); color:var(--text); font:var(--s0)/1.5 var(--sans); display:flex; flex-direction:column; }
button, input, textarea { font:inherit; color:inherit; }
button { cursor:pointer; }
:focus-visible { outline:2px solid var(--focus); outline-offset:2px; }
.grow { flex:1; }
.muted { color:var(--muted); }

.top { height:var(--header-h); display:flex; align-items:center; gap:16px; padding:0 24px; border-bottom:1px solid var(--line); background:var(--surface); flex:none; }
.mark { font:600 var(--s3)/1 var(--serif); letter-spacing:.14em; }
nav { display:flex; gap:4px; }
nav button, .ghost { background:none; border:1px solid transparent; border-radius:var(--r-control); padding:6px 12px; color:var(--text-2); }
nav button:hover, .ghost:hover { background:var(--raised); }
nav button.on { color:var(--text); border-color:var(--line-strong); background:var(--raised); }
.conn { font-size:var(--s-1); color:var(--muted); }
.conn::before { content:''; display:inline-block; width:8px; height:8px; border-radius:50%; background:var(--muted); margin-right:6px; }
.conn.ok::before { background:var(--good); } .conn.bad::before { background:var(--forget-fill); }

.page { flex:1; min-height:0; display:flex; flex-direction:column; }
.page.wide { max-width:1180px; width:100%; margin:0 auto; padding:28px 32px; overflow:auto; display:block; }
.transcript { flex:1; overflow:auto; padding:28px 24px 12px; }
.transcript > * { max-width:1040px; margin:0 auto 26px; }
.welcome { padding-top:8vh; max-width:620px !important; }
.welcome h1 { font:500 var(--s5)/1.2 var(--serif); margin:0 0 12px; }
.welcome p { color:var(--text-2); font-size:var(--s1); }

.msg.user { display:flex; justify-content:flex-end; }
.msg.user .bubble { max-width:min(560px,88%); padding:10px 16px; background:var(--raised); border:1px solid var(--line); border-radius:16px 16px 4px 16px; font:var(--s2)/1.5 var(--serif); white-space:pre-wrap; }
.msg.user .tag { display:block; font:var(--s-1) var(--sans); color:var(--muted); margin-top:4px; }
.msg.bot .bubble { max-width:680px; font:var(--s2)/1.6 var(--serif); white-space:pre-wrap; padding:2px 0 2px 14px; border-left:2px solid var(--hl); cursor:pointer; }
.msg.bot.abstain .bubble { border-left:2px dashed var(--line-strong); color:var(--text-2); }
.msg.bot.error .bubble { border-left-color:var(--forget-fill); cursor:default; }
.msg.bot .meta { margin:6px 0 0 14px; font-size:var(--s-1); color:var(--muted); }
.msg.bot .meta button { margin-left:10px; }
.msg.note .bubble { font-size:var(--s-1); color:var(--muted); }
.dots::after { content:'…'; animation:blink 1s steps(3) infinite; } @keyframes blink { 50% { opacity:.2; } }

.composer { flex:none; width:100%; max-width:1088px; margin:0 auto; padding:8px 24px 18px; }
.modes { display:flex; gap:6px; margin-bottom:8px; }
.modes label { border:1px solid var(--line); border-radius:var(--r-control); padding:4px 12px; color:var(--text-2); cursor:pointer; }
.modes label:has(input:checked) { background:var(--hl-soft); border-color:var(--hl); color:var(--text); }
.modes input { position:absolute; opacity:0; pointer-events:none; }
.world { display:flex; gap:8px; align-items:center; margin-bottom:8px; font-size:var(--s-1); color:var(--muted); }
.world input { flex:1; background:var(--sunken); border:1px solid var(--line); border-radius:var(--r-control); padding:6px 10px; }
.box { display:flex; gap:8px; align-items:flex-end; background:var(--surface); border:1px solid var(--line-strong); border-radius:var(--r-composer); padding:8px 8px 8px 16px; }
.box textarea { flex:1; background:none; border:0; resize:none; outline:0; font:var(--s2)/1.5 var(--serif); max-height:30vh; }
.ink { background:var(--ink-button); color:var(--ink-button-text); border:0; border-radius:var(--r-control); padding:8px 18px; font-weight:600; }
.ink:disabled { opacity:.5; cursor:default; }
.danger { background:var(--forget-bg); color:var(--forget); border:1px solid var(--forget); border-radius:var(--r-control); padding:8px 16px; }

.bar { display:flex; align-items:center; gap:14px; flex-wrap:wrap; margin-bottom:18px; }
h2 { font:500 var(--s3)/1.2 var(--serif); margin:0; } h3 { font:500 var(--s2)/1.2 var(--serif); margin:32px 0 4px; }
.chips { display:flex; gap:4px; } .chips button { background:none; border:1px solid var(--line); border-radius:99px; padding:3px 12px; color:var(--text-2); }
.chips button.on { background:var(--hl-soft); border-color:var(--hl); color:var(--text); }
.card { background:var(--surface); border:1px solid var(--line); border-radius:var(--r-panel); padding:14px 16px; margin-bottom:10px; }
.card.old { background:var(--sunken); }
.card .head { display:flex; gap:10px; align-items:baseline; flex-wrap:wrap; }
.card .val { font:var(--s2)/1.4 var(--serif); }
.card .quote { margin-top:6px; color:var(--text-2); font:italic var(--s1)/1.5 var(--serif); }
.badge { font-size:var(--s-1); border:1px solid var(--line-strong); border-radius:99px; padding:0 8px; color:var(--muted); }
.badge.other { color:var(--planned); border-color:var(--planned); } .badge.history { color:var(--hl); border-color:var(--hl); }
.badge.good { color:var(--good); border-color:var(--good); } .badge.bad { color:var(--forget); border-color:var(--forget); }
.empty, .errbox { border:1px dashed var(--line-strong); border-radius:var(--r-panel); padding:24px; color:var(--muted); }
.errbox { color:var(--forget); border-color:var(--forget); background:var(--forget-bg); }
.sys { display:grid; grid-template-columns:max-content 1fr; gap:8px 24px; margin:18px 0; } .sys dt { color:var(--muted); } .sys dd { margin:0; word-break:break-all; }

.drawer { position:fixed; top:0; right:0; bottom:0; width:min(480px,100%); background:var(--surface); border-left:1px solid var(--line); box-shadow:var(--shadow-pop); z-index:20; overflow:auto; padding:20px; }
.drawer-head { display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; }
.drawer h4 { margin:18px 0 6px; font-size:var(--s-1); letter-spacing:.06em; text-transform:uppercase; color:var(--muted); }
.ev { border-left:2px solid var(--hl); padding:2px 0 2px 12px; margin-bottom:10px; font:var(--s1)/1.5 var(--serif); } .ev small { display:block; font:var(--s-1) var(--sans); color:var(--muted); }
.step { font:var(--s-1) ui-monospace,Consolas,monospace; color:var(--text-2); margin-bottom:4px; word-break:break-word; }
.scrim { position:fixed; inset:0; background:var(--scrim); z-index:10; }
dialog { background:var(--surface); color:var(--text); border:1px solid var(--line-strong); border-radius:var(--r-panel); box-shadow:var(--shadow-pop); padding:24px; max-width:440px; }
dialog::backdrop { background:var(--scrim); } dialog .row { display:flex; gap:8px; justify-content:flex-end; margin-top:16px; }

@media (max-width:900px) { .top { padding:0 12px; gap:8px; } .page.wide { padding:20px 16px; } }
@media (max-width:720px) { .mark { display:none; } .transcript { padding:20px 14px 8px; } .composer { padding:8px 14px 14px; } .box textarea { font-size:var(--s1); } }
@media (prefers-reduced-motion:reduce) { * { animation:none !important; transition:none !important; } }

// HUSH UI: real calls only. /api/* is proxied to the memory service; /view/memory is a read-only look at its store.
const $ = (id) => document.getElementById(id);
const el = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; };
const store = { get(k) { try { return localStorage.getItem(k); } catch { return null; } }, set(k, v) { try { localStorage.setItem(k, v); } catch { /* private mode */ } } };

async function api(name, body) {
  const r = await fetch('/api/' + name, body === undefined ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const text = await r.text();
  let data = {}; try { data = JSON.parse(text); } catch { /* keep {} */ }
  if (!r.ok) throw new Error(data.error || `HTTP ${r.status}`);
  return data;
}
const view = async () => (await fetch('/view/memory')).json();
const nowIso = () => { const d = new Date(), p = (n) => String(n).padStart(2, '0'), o = -d.getTimezoneOffset(), a = Math.abs(o);
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}${o < 0 ? '-' : '+'}${p(Math.floor(a / 60))}:${p(a % 60)}`; };
let seq = 0; const newId = () => `ui${Date.now().toString(36)}${++seq}`;

// ---- theme, navigation, connection -----------------------------------------------------------
document.documentElement.dataset.theme = store.get('theme') || 'dark';
$('theme').onclick = () => { const t = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'; document.documentElement.dataset.theme = t; store.set('theme', t); };
function show(page) {
  document.querySelectorAll('.page').forEach((p) => { p.hidden = p.id !== 'page-' + page; });
  document.querySelectorAll('#nav button').forEach((b) => b.classList.toggle('on', b.dataset.page === page));
  if (page === 'memories') loadMemories(); if (page === 'system') loadSystem();
}
$('nav').onclick = (e) => e.target.dataset.page && show(e.target.dataset.page);
async function ping() {
  try { await api('health'); $('conn').textContent = 'service connected'; $('conn').className = 'conn ok'; return true; }
  catch (e) { $('conn').textContent = 'service unreachable'; $('conn').className = 'conn bad'; return false; }
}
ping(); setInterval(ping, 15000);

// ---- chat ------------------------------------------------------------------------------------
const MODE_HINT = { say: 'Tell the assistant something to remember…', ask: 'Ask what the assistant knows…', act: 'Give the assistant a job to do…' };
const mode = () => document.querySelector('input[name=mode]:checked').value;
document.querySelectorAll('input[name=mode]').forEach((r) => r.onchange = () => { $('input').placeholder = MODE_HINT[mode()]; $('world-row').hidden = mode() !== 'act'; });
$('input').addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); $('composer').requestSubmit(); } });

function add(node) { $('welcome').hidden = true; $('transcript').appendChild(node); node.scrollIntoView({ block: 'end' }); return node; }
function userBubble(text, tag) { const m = el('div', 'msg user'), b = el('div', 'bubble', text); if (tag) b.appendChild(el('span', 'tag', tag)); m.appendChild(b); return add(m); }

async function run(m, text, node) {   // node: the assistant bubble, filled in place so Retry can reuse it
  node.className = 'msg bot'; node.replaceChildren(el('div', 'bubble dots', 'Working'));
  try {
    if (m === 'say') {
      const before = await view();
      await api('message', { message: { id: newId(), ts: nowIso(), type: 'chat', turns: [{ role: 'user', content: text }] } });
      const after = await view();
      node.className = 'msg bot note';
      node.replaceChildren(el('div', 'bubble', after.available
        ? `Sent. Memory now holds ${after.counts.active} current and ${after.counts.superseded} earlier fact(s) (${after.counts.active - before.counts.active >= 0 ? '+' : ''}${after.counts.active - before.counts.active} current). See the Memories page for what was stored.`
        : 'Sent. The memory view is unavailable here, so I cannot show what was stored.'));
    } else if (m === 'ask') {
      const out = await api('answer', { question: text });
      const abstain = !out.evidence.length;
      node.className = 'msg bot' + (abstain ? ' abstain' : '');
      const b = el('div', 'bubble', out.answer || '(empty answer)'); b.onclick = () => openAnswer(text, out);
      node.replaceChildren(b, el('div', 'meta', abstain ? 'No supporting memory. Click for details.' : `${out.evidence.length} source(s). Click the answer to inspect.`));
    } else {
      const world = $('world').value.trim();
      const out = await api('act', { request: text, mcp_url: world.replace(/\/tools$/, '/mcp'), tools_url: world });
      const b = el('div', 'bubble', out.reply || '(no reply)'); b.onclick = () => openAct(text, out);
      node.replaceChildren(b, el('div', 'meta', `${out.trace.filter((t) => t.step === 'tool').length} tool call(s). Click the reply to inspect.`));
    }
  } catch (e) {
    node.className = 'msg bot error';
    const retry = el('button', 'ghost', 'Retry'); retry.onclick = () => run(m, text, node);
    const meta = el('div', 'meta', ''); meta.append('Could not complete this. ', retry);
    node.replaceChildren(el('div', 'bubble', e.message), meta);
  }
}
$('composer').onsubmit = async (e) => {
  e.preventDefault();
  const text = $('input').value.trim(), m = mode(); if (!text) return;
  $('input').value = ''; $('send').disabled = true;
  userBubble(text, { say: 'told', ask: 'asked', act: 'job' }[m]);
  await run(m, text, add(el('div', 'msg bot')));
  $('send').disabled = false; $('input').focus();
};

// ---- evidence drawer -------------------------------------------------------------------------
function drawer(title, build) { $('drawer-title').textContent = title; const b = $('drawer-body'); b.replaceChildren(); build(b); $('drawer').hidden = $('scrim').hidden = false; $('close').focus(); }
const closeDrawer = () => { $('drawer').hidden = $('scrim').hidden = true; };
$('close').onclick = $('scrim').onclick = closeDrawer;
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeDrawer(); });
const steps = (b, trace) => { b.appendChild(el('h4', null, 'How it was found')); (trace || []).forEach((t) => b.appendChild(el('div', 'step', JSON.stringify(t)))); };
function openAnswer(q, out) {
  drawer('Answer details', (b) => {
    b.appendChild(el('h4', null, 'Question')); b.appendChild(el('div', null, q));
    b.appendChild(el('h4', null, out.evidence.length ? 'Evidence used' : 'Abstained'));
    if (!out.evidence.length) b.appendChild(el('div', 'muted', 'Nothing stored supports an answer, so none was given.'));
    out.evidence.forEach((ev) => { const d = el('div', 'ev', ev.text); d.appendChild(el('small', null, 'message ' + ev.message_id)); b.appendChild(d); });
    steps(b, out.trace);
  });
}
function openAct(q, out) {
  drawer('Job details', (b) => {
    b.appendChild(el('h4', null, 'Request')); b.appendChild(el('div', null, q));
    b.appendChild(el('h4', null, 'Steps taken')); out.trace.filter((t) => t.step === 'tool').forEach((t) => b.appendChild(el('div', 'step', `${t.name} ${t.args} → ${t.result}`)));
    if (!out.trace.some((t) => t.step === 'tool')) b.appendChild(el('div', 'muted', 'No tools were called.'));
    steps(b, out.trace.filter((t) => t.step !== 'tool'));
  });
}

// ---- memories --------------------------------------------------------------------------------
let filter = 'active', last = null;
$('filters').onclick = (e) => { if (!e.target.dataset.f) return; filter = e.target.dataset.f; document.querySelectorAll('#filters button').forEach((b) => b.classList.toggle('on', b === e.target)); render(); };
$('refresh').onclick = loadMemories;
const day = (s) => (s || '').slice(0, 10);
async function loadMemories() {
  $('facts').replaceChildren(el('div', 'empty dots', 'Loading'));
  try { last = await view(); render(); } catch (e) { $('facts').replaceChildren(el('div', 'errbox', 'Could not read memory: ' + e.message)); }
}
function render() {
  if (!last) return;
  const c = last.counts; $('counts').textContent = last.available ? `${c.active} current · ${c.superseded} earlier · ${c.sources} source(s)` : '';
  const rows = last.facts.filter((f) => filter === 'all' || f.status === filter);
  const box = $('facts'); box.replaceChildren();
  if (!last.available) box.appendChild(el('div', 'empty', 'No memory store found on this machine. Start the service locally (python server.py) with the same MEMORY_DB, then refresh.'));
  else if (!rows.length) box.appendChild(el('div', 'empty', filter === 'superseded' ? 'No earlier versions yet. A correction keeps the old value here.' : 'Nothing stored yet. Tell the assistant something on the Chat page.'));
  rows.forEach((f) => {
    const card = el('div', 'card' + (f.status === 'active' ? '' : ' old')), head = el('div', 'head');
    head.append(el('span', 'val', `${f.subject} · ${f.relation}: ${f.value}`), el('span', 'badge', f.kind.toLowerCase()),
      el('span', 'badge' + (f.attribution === 'other' ? ' other' : ''), f.attribution === 'other' ? 'said by someone else' : 'about you'));
    if (f.when_date) head.append(el('span', 'badge', f.when_date));
    if (f.status !== 'active') head.append(el('span', 'badge history', 'replaced ' + day(f.ended_ts)));
    card.append(head, el('div', 'quote', `“${f.quote}”`), el('div', 'muted', `from message ${f.first_message_id} · noted ${day(f.created_ts)} · ${f.evidence_count} source(s)`));
    box.appendChild(card);
  });
  const fb = $('forgets'); fb.replaceChildren();
  if (!last.forgets.length) fb.appendChild(el('div', 'empty', 'Nothing has been forgotten in this run.'));
  last.forgets.forEach((r) => { const d = el('div', 'card'), h = el('div', 'head');
    h.append(el('span', null, `${r.facts_removed} fact(s) and ${r.sources_removed} source(s) erased`), el('span', 'badge ' + (r.verified ? 'good' : 'bad'), r.verified ? 'verified' : `${r.problems} problem(s)`), el('span', 'muted', day(r.ts)));
    d.appendChild(h); fb.appendChild(d); });
}

// ---- system ----------------------------------------------------------------------------------
async function loadSystem() {
  const dl = $('sys'); dl.replaceChildren(); const row = (k, v) => dl.append(el('dt', null, k), el('dd', null, v));
  const up = await ping(); row('Memory service', up ? 'reachable (GET /health ok)' : 'unreachable: start it with  python server.py');
  try { const v = await view(); row('Memory store', v.available ? `found · ${v.counts.sources} source(s) · latest message time ${v.now || 'n/a'}` : 'not found on this machine'); }
  catch (e) { row('Memory store', 'could not be read: ' + e.message); }
}
$('reset').onclick = () => { $('confirm-text').textContent = 'Wipe ALL stored memory for a fresh run? This cannot be undone.'; $('confirm').showModal(); };
$('confirm').addEventListener('close', async () => {
  if ($('confirm').returnValue !== 'ok') return;
  try { await api('reset', {}); last = null; $('transcript').querySelectorAll('.msg').forEach((n) => n.remove()); $('welcome').hidden = false; await loadSystem(); alert('Memory wiped.'); }
  catch (e) { alert('Reset failed: ' + e.message); }
});
show('chat');

