"""Persistent conversations inside one project's database. Chats are a log of what was said, not a memory source:
deleting a chat never deletes memories, and a Forget redacts any chat message that carried the erased information."""
import json
from datetime import datetime

from backend.source.dal.db_session import Database


def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


class ChatRepository:
    def __init__(self, database: Database) -> None:
        self.db, self.lock = database.db, database.lock

    def create(self, title: str = "New chat") -> dict:
        with self.lock, self.db:
            cur = self.db.execute("INSERT INTO conversations(title, created_ts, updated_ts) VALUES(?,?,?)", (title[:80] or "New chat", now_iso(), now_iso()))
        return self.get(cur.lastrowid)

    def get(self, cid: int) -> dict | None:
        with self.lock:
            r = self.db.execute("SELECT * FROM conversations WHERE id=?", (cid,)).fetchone()
        return dict(r) if r else None

    def list(self) -> list[dict]:
        with self.lock:
            return [dict(r) for r in self.db.execute(
                "SELECT c.id, c.title, c.updated_ts, (SELECT COUNT(*) FROM chat_messages m WHERE m.conversation_id=c.id) AS messages "
                "FROM conversations c ORDER BY c.updated_ts DESC, c.id DESC")]

    def rename(self, cid: int, title: str) -> bool:
        with self.lock, self.db:
            return self.db.execute("UPDATE conversations SET title=? WHERE id=?", (title.strip()[:80] or "Untitled", cid)).rowcount > 0

    def delete(self, cid: int) -> bool:
        with self.lock, self.db:
            self.db.execute("DELETE FROM chat_messages WHERE conversation_id=?", (cid,))
            return self.db.execute("DELETE FROM conversations WHERE id=?", (cid,)).rowcount > 0

    def clear(self) -> None:
        with self.lock, self.db:
            self.db.execute("DELETE FROM chat_messages")
            self.db.execute("DELETE FROM conversations")

    def messages(self, cid: int) -> list[dict]:
        with self.lock:
            rows = self.db.execute("SELECT * FROM chat_messages WHERE conversation_id=? ORDER BY id", (cid,)).fetchall()
        return [{**dict(r), "payload": json.loads(r["payload"]) if r["payload"] else None} for r in rows]

    def append(self, cid: int, role: str, mode: str, content: str, payload=None) -> dict:
        with self.lock, self.db:
            cur = self.db.execute("INSERT INTO chat_messages(conversation_id, role, mode, content, payload, ts) VALUES(?,?,?,?,?,?)",
                                  (cid, role, mode, content, json.dumps(payload, ensure_ascii=False) if payload is not None else None, now_iso()))
            self.db.execute("UPDATE conversations SET updated_ts=?, title=CASE WHEN title='New chat' AND ?='user' THEN ? ELSE title END WHERE id=?",
                            (now_iso(), role, content[:40].strip() or "New chat", cid))
        return {"id": cur.lastrowid, "role": role, "mode": mode, "content": content, "payload": payload}

"""The registry of product projects (id, name). Each project's memory is a separate SQLite file next to this registry,
so isolation is structural: nothing in one project's database can refer to or be queried together with another's.
Ids are generated here, never taken from a caller, so they cannot be used to reach other files."""
import re
import secrets
import sqlite3
import threading
from datetime import datetime
from pathlib import Path

ID = re.compile(r"^p_[0-9a-f]{8}$")


class ProjectRepository:
    def __init__(self, root: Path) -> None:
        root.mkdir(parents=True, exist_ok=True)
        (root / "projects").mkdir(exist_ok=True)
        self.root, self.lock = root, threading.RLock()
        self.db = sqlite3.connect(str(root / "registry.db"), check_same_thread=False)
        self.db.row_factory = sqlite3.Row
        self.db.execute("CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, created_ts TEXT NOT NULL)")
        self.db.commit()

    def path(self, pid: str) -> Path:
        if not ID.match(pid or ""):
            raise KeyError(pid)
        return self.root / "projects" / f"{pid}.db"

    def list(self) -> list[dict]:
        with self.lock:
            return [dict(r) for r in self.db.execute("SELECT id, name, created_ts FROM projects ORDER BY created_ts, id")]

    def get(self, pid: str) -> dict:
        with self.lock:
            r = self.db.execute("SELECT id, name, created_ts FROM projects WHERE id=?", (pid,)).fetchone() if ID.match(pid or "") else None
        if not r:
            raise KeyError(pid)
        return dict(r)

    def create(self, name: str) -> dict:
        name = (name or "").strip()
        if not 1 <= len(name) <= 60:
            raise ValueError("A project name must be 1 to 60 characters.")
        with self.lock, self.db:
            if self.db.execute("SELECT 1 FROM projects WHERE lower(name)=lower(?)", (name,)).fetchone():
                raise ValueError("A project with that name already exists.")
            pid = "p_" + secrets.token_hex(4)
            self.db.execute("INSERT INTO projects(id, name, created_ts) VALUES(?,?,?)", (pid, name, datetime.now().astimezone().isoformat(timespec="seconds")))
        return self.get(pid)

    def rename(self, pid: str, name: str) -> dict:
        self.get(pid)
        name = (name or "").strip()
        if not 1 <= len(name) <= 60:
            raise ValueError("A project name must be 1 to 60 characters.")
        with self.lock, self.db:
            if self.db.execute("SELECT 1 FROM projects WHERE lower(name)=lower(?) AND id!=?", (name, pid)).fetchone():
                raise ValueError("A project with that name already exists.")
            self.db.execute("UPDATE projects SET name=? WHERE id=?", (name, pid))
        return self.get(pid)

    def delete(self, pid: str) -> None:
        self.get(pid)
        with self.lock, self.db:
            self.db.execute("DELETE FROM projects WHERE id=?", (pid,))

"""The product workspace: projects, persistent conversations, and honest receipts for Tell / Ask / Do.

Every project is its own MemorySystem over its own SQLite file (see ProjectRepository), so extraction, reconciliation,
retrieval, evidence, dependencies, embeddings, forgotten-term hashes and deletion are isolated by construction.
This workspace is separate from the evaluation service's database: the official /reset cannot touch it and it cannot
read the evaluation memory. It runs in the UI process; server.py is unchanged.
"""
import shutil
import uuid
from pathlib import Path

from backend.source.api.memory_system import MemorySystem
from backend.source.dal.repositories.chat_repository import ChatRepository, now_iso
from backend.source.dal.repositories.memory_view import snapshot
from backend.source.dal.repositories.project_repository import ProjectRepository

MODES = {"tell", "ask", "do"}
FORGOTTEN_REQUEST = "(You asked me to forget something. The request text was not kept.)"


class WorkspaceError(Exception):
    """A request the caller got wrong (unknown project or chat, bad input): shown to the user as is."""


class Workspace:
    def __init__(self, root, llm_fn=None, chat_fn=None, embedder=None) -> None:
        self.projects_repo = ProjectRepository(Path(root))
        self._llm, self._chat, self._embedder = llm_fn, chat_fn, embedder
        self._systems: dict = {}
        if not self.projects_repo.list():
            self.projects_repo.create("General")

    # -- projects -----------------------------------------------------------------
    def list_projects(self) -> list[dict]:
        return self.projects_repo.list()

    def create_project(self, name: str) -> dict:
        try:
            return self.projects_repo.create(name)
        except ValueError as e:
            raise WorkspaceError(str(e))

    def rename_project(self, pid: str, name: str) -> dict:
        try:
            return self.projects_repo.rename(pid, name)
        except KeyError:
            raise WorkspaceError("Unknown project.")
        except ValueError as e:
            raise WorkspaceError(str(e))

    def delete_project(self, pid: str) -> None:
        """Removes the project's whole database file: memories, conversations, vectors, everything."""
        path = self._path(pid)
        system = self._systems.pop(pid, None)
        if system:
            system.close()
        self.projects_repo.delete(pid)
        for suffix in ("", "-journal", "-wal", "-shm"):
            Path(str(path) + suffix).unlink(missing_ok=True)
        if not self.projects_repo.list():
            self.projects_repo.create("General")

    def reset_all(self) -> None:
        for p in self.projects_repo.list():
            self.delete_project(p["id"])

    def _path(self, pid: str) -> Path:
        try:
            self.projects_repo.get(pid)
            return self.projects_repo.path(pid)
        except KeyError:
            raise WorkspaceError("Unknown project.")

    def system(self, pid: str) -> MemorySystem:
        if pid not in self._systems:
            self._systems[pid] = MemorySystem(llm_fn=self._llm, chat_fn=self._chat, embedder=self._embedder, db_path=str(self._path(pid)))
        return self._systems[pid]

    def _chats(self, pid: str) -> ChatRepository:
        return ChatRepository(self.system(pid).database)

    # -- conversations ------------------------------------------------------------
    def list_chats(self, pid: str) -> list[dict]:
        return self._chats(pid).list()

    def new_chat(self, pid: str) -> dict:
        return self._chats(pid).create()

    def open_chat(self, pid: str, cid: int) -> dict:
        chats = self._chats(pid)
        conv = chats.get(cid)
        if not conv:
            raise WorkspaceError("Unknown conversation.")
        return {**conv, "messages": chats.messages(cid)}

    def rename_chat(self, pid: str, cid: int, title: str) -> None:
        if not self._chats(pid).rename(cid, title):
            raise WorkspaceError("Unknown conversation.")

    def delete_chat(self, pid: str, cid: int) -> None:
        if not self._chats(pid).delete(cid):  # memories stay: a chat is a log, not the memory
            raise WorkspaceError("Unknown conversation.")

    def clear_chats(self, pid: str) -> None:
        self._chats(pid).clear()

    # -- Tell / Ask / Do -----------------------------------------------------------
    def send(self, pid: str, cid: int, mode: str, text: str, world_url: str = "") -> dict:
        text = (text or "").strip()
        if mode not in MODES or not text or len(text) > 4000:
            raise WorkspaceError("Choose Tell, Ask or Do and write between 1 and 4000 characters.")
        system, chats = self.system(pid), self._chats(pid)
        if not chats.get(cid):
            raise WorkspaceError("Unknown conversation.")
        stored_user, payload = text, None
        if mode == "tell":
            mid, before = "u" + uuid.uuid4().hex[:12], self._state(system)
            system.add_message({"id": mid, "ts": now_iso(), "type": "chat", "turns": [{"role": "user", "content": text}]})
            payload = self._receipt(system, before, mid)
            reply = payload["headline"]
            if payload["extraction"] == "forget_request":
                stored_user = FORGOTTEN_REQUEST  # the transcript must not keep what the user asked to forget
        elif mode == "ask":
            out = system.answer(text)
            reply, payload = out["answer"], {"evidence": out["evidence"], "trace": out["trace"]}
        else:
            if not world_url.startswith(("http://", "https://")):
                raise WorkspaceError("Enter the tools URL of the mock world (http://...) to run a job.")
            out = system.act(text, {"tools_url": world_url, "mcp_url": world_url.rsplit("/tools", 1)[0] + "/mcp"})
            reply, payload = out["reply"], {"trace": out["trace"]}
        return {"user": chats.append(cid, "user", mode, stored_user), "assistant": chats.append(cid, "assistant", mode, reply, payload)}

    # -- receipts: what a Tell really did, from before/after states, never from the model's say-so -----------
    @staticmethod
    def _state(system: MemorySystem) -> dict:
        with system.repo.lock:
            facts = {r["id"]: dict(r) for r in system.repo.db.execute(
                "SELECT f.id, f.subject, f.relation, f.value, f.status, f.conflict_with, "
                "(SELECT COUNT(*) FROM evidence e WHERE e.fact_id=f.id) AS ev FROM facts f")}
            forgets = system.repo.db.execute("SELECT COUNT(*) FROM forget_log").fetchone()[0]
        return {"facts": facts, "forgets": forgets}

    def _receipt(self, system: MemorySystem, before: dict, mid: str) -> dict:
        after = self._state(system)
        text = lambda f: f"{f['subject']} · {f['relation']}: {f['value']}"  # noqa: E731
        b, a = before["facts"], after["facts"]
        saved = [text(f) for i, f in a.items() if i not in b and f["status"] == "active"]
        history = [text(f) for i, f in a.items() if i not in b and f["status"] != "active"]
        updated = [{"was": text(b[i]), "now": ""} for i, f in a.items() if i in b and b[i]["status"] == "active" and f["status"] == "superseded"]
        newest = [text(f) for i, f in a.items() if i not in b and f["status"] == "active"]
        for u, n in zip(updated, newest[::-1] or [""] * len(updated)):
            u["now"] = n
        stale = [text(b[i]) for i, f in a.items() if i in b and b[i]["status"] == "active" and f["status"] == "stale"]
        again = [text(f) for i, f in a.items() if i in b and f["ev"] > b[i]["ev"] and f["status"] == "active"]
        conflicts = [text(f) for i, f in a.items() if i not in b and f["conflict_with"]]
        removed = len(b) - len([i for i in b if i in a])
        forgot = after["forgets"] > before["forgets"]
        src = system.repo.source(mid)
        extraction = src["extraction"] if src else "unknown"
        if forgot or extraction in ("forget_request", "forget_unresolved"):
            headline = (f"Forgot {removed} fact(s) and verified the removal." if forgot and removed else
                        "I couldn't work out what to forget, so nothing was removed." if extraction == "forget_unresolved" else
                        "I found nothing stored that matches, so nothing was removed.")
        elif extraction == "failed":
            headline = "I couldn't process that just now (the model was unavailable), so no facts were saved. The message itself is kept."
        elif saved or updated or again or history:
            bits = [f"saved {len(saved)}" if saved else "", f"updated {len(updated)}" if updated else "",
                    f"already knew {len(again)}" if again else "", f"kept {len(history)} as history" if history else ""]
            headline = "Done: " + ", ".join(x for x in bits if x) + "."
        else:
            headline = "Nothing in that was worth remembering, so nothing was saved."
        return {"headline": headline, "extraction": extraction, "saved": saved, "updated": updated, "history": history, "stale": stale,
                "already_known": again, "conflicts": conflicts, "forgotten": removed if forgot else 0}

    # -- memory timeline ------------------------------------------------------------
    def memory(self, pid: str) -> dict:
        return snapshot(self.system(pid).database.db)

    def system_info(self) -> dict:
        from backend.source.utils import config
        emb = self._embedder
        return {"projects": len(self.projects_repo.list()), "root": str(self.projects_repo.root), "model": config.MODEL,
                "model_configured": bool(config.API_KEY), "semantic": bool(getattr(emb, "available", False)) if emb else False}

