// HUSH product UI. Real calls only: everything goes to the workspace API in frontend/serve.py (projects, conversations,
// Tell/Ask/Do, memory timeline). A response that arrives after the user switched project or chat is ignored.
const $ = (id) => document.getElementById(id);
const el = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; };
const store = { get(k) { try { return localStorage.getItem(k); } catch { return null; } }, set(k, v) { try { localStorage.setItem(k, v); } catch { /* private mode */ } } };
const S = { pid: null, cid: null, projects: [], tok: 0, facts: null, filter: 'active', page: 'chat' };

async function call(method, path, body) {
  const r = await fetch(path, method === 'GET' ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}) });
  const data = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(data.error || `HTTP ${r.status}`);
  return data;
}
const P = (p) => `/p/${S.pid}${p}`;
const day = (s) => (s || '').slice(0, 10);

// ---- theme, navigation ---------------------------------------------------------------------------
document.documentElement.dataset.theme = store.get('theme') || 'dark';
$('theme').onclick = () => { const t = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'; document.documentElement.dataset.theme = t; store.set('theme', t); };
function show(page) {
  S.page = page;
  document.querySelectorAll('.page').forEach((p) => { p.hidden = p.id !== 'page-' + page; });
  document.querySelectorAll('#nav button').forEach((b) => b.classList.toggle('on', b.dataset.page === page));
  $('rail-toggle').hidden = page !== 'chat';
  if (page === 'memories') loadMemories();
  if (page === 'system') loadSystem();
}
$('nav').onclick = (e) => e.target.dataset.page && show(e.target.dataset.page);
$('rail-toggle').onclick = () => $('rail').classList.toggle('open');

// ---- dialogs ---------------------------------------------------------------------------------------
function ask({ text, input, value = '', danger = false, ok = 'OK', check }) {
  return new Promise((resolve) => {
    $('dlg-text').textContent = text; $('dlg-input').hidden = !input; $('dlg-input').value = value; $('dlg-err').hidden = true;
    $('dlg-ok').textContent = ok; $('dlg-ok').className = danger ? 'danger' : 'ink';
    const dlg = $('dlg');
    const done = () => { dlg.removeEventListener('close', done); resolve(dlg.returnValue === 'ok' ? (input ? $('dlg-input').value.trim() : true) : null); };
    dlg.addEventListener('close', done); dlg.showModal(); if (input) $('dlg-input').focus();
  });
}

// ---- projects ------------------------------------------------------------------------------------------
async function loadProjects(prefer) {
  S.projects = (await call('GET', '/p/projects')).projects;
  const want = prefer || S.pid || store.get('pid');
  const cur = S.projects.find((p) => p.id === want) || S.projects[0];
  $('proj-name').textContent = cur.name;
  if (cur.id !== S.pid) await switchProject(cur.id); else renderProjectMenu();
}
function renderProjectMenu() {
  const m = $('proj-menu'); m.replaceChildren();
  S.projects.forEach((p) => { const b = el('button', 'menu-item' + (p.id === S.pid ? ' on' : ''), p.name); b.setAttribute('role', 'menuitem'); b.onclick = () => { closeMenu(); if (p.id !== S.pid) switchProject(p.id); }; m.appendChild(b); });
  m.appendChild(el('hr'));
  [['New project…', newProject], ['Rename this project…', renameProject], ['Delete this project…', deleteProject]].forEach(([t, fn]) => { const b = el('button', 'menu-item', t); b.setAttribute('role', 'menuitem'); b.onclick = () => { closeMenu(); fn(); }; m.appendChild(b); });
}
const closeMenu = () => { $('proj-menu').hidden = true; $('proj-btn').setAttribute('aria-expanded', 'false'); };
$('proj-btn').onclick = (e) => { e.stopPropagation(); const open = $('proj-menu').hidden; $('proj-menu').hidden = !open; $('proj-btn').setAttribute('aria-expanded', String(open)); };
document.addEventListener('click', closeMenu);
async function switchProject(pid) {
  S.tok++; S.pid = pid; S.cid = null; S.facts = null; store.set('pid', pid);
