  chats.forEach((c) => {
    const row = el('div', 'chat-row' + (c.id === S.cid ? ' on' : '')), b = el('button', 'chat-title', c.title);
    b.title = `${c.messages} message(s)`; b.onclick = () => { $('rail').classList.remove('open'); openChat(c.id); };
