    d.onclick = async () => { if (await ask({ text: 'Delete this conversation? The memories it created stay.', danger: true, ok: 'Delete' })) { await call('POST', P(`/chats/${c.id}/delete`)); if (S.cid === c.id) { S.cid = null; renderTranscript([]); } const tok = S.tok; const { chats: rest } = await call('GET', P('/chats')); if (tok === S.tok) { renderRail(rest); if (S.cid === null && rest.length) openChat(rest[0].id); } } };
