const MODE_HINT = { tell: 'Tell me something to remember. To forget something, say so here.', ask: 'Ask what I know. Ask only reads memory.', do: 'Give me a job to do with the connected tools.' };
const mode = () => document.querySelector('input[name=mode]:checked').value;
document.querySelectorAll('input[name=mode]').forEach((r) => r.onchange = () => { $('input').placeholder = MODE_HINT[mode()]; $('world-row').hidden = mode() !== 'do'; });
$('input').addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); $('composer').requestSubmit(); } });

function renderTranscript(msgs) {
  const t = $('transcript'); t.replaceChildren();
  if (!msgs.length) {
    const w = el('section', 'welcome'); w.append(el('h1', null, 'Tell me things. Ask me later.'),
      el('p', null, 'Everything here belongs to this project only. Tell me what to remember, ask what I know, hand me a job, or ask me to forget something. Answers show the words they relied on.'));
    t.appendChild(w); return;
  }
  msgs.forEach((m) => t.appendChild(m.role === 'user' ? userBubble(m) : botBubble(m)));
  t.lastChild.scrollIntoView({ block: 'end' });
}
const TAG = { tell: 'told', ask: 'asked', do: 'job' };
function userBubble(m) { const w = el('div', 'msg user'), b = el('div', 'bubble', m.content); b.appendChild(el('span', 'tag', TAG[m.mode] || '')); w.appendChild(b); return w; }
function list(title, items, render) { const d = el('div', 'rc'); d.appendChild(el('strong', null, title)); items.forEach((i) => d.appendChild(el('div', 'rc-item', render ? render(i) : i))); return d; }
function botBubble(m) {
  const w = el('div', 'msg bot'), p = m.payload || {};
  if (m.mode === 'tell') {
    w.classList.add('note'); const b = el('div', 'bubble'); b.appendChild(el('div', null, m.content));
    if (p.saved && p.saved.length) b.appendChild(list('Saved', p.saved));
    if (p.updated && p.updated.length) b.appendChild(list('Updated', p.updated, (u) => `${u.was}  →  ${u.now}`));
    if (p.already_known && p.already_known.length) b.appendChild(list('Already known (evidence added)', p.already_known));
    if (p.history && p.history.length) b.appendChild(list('Kept as history', p.history));
    if (p.stale && p.stale.length) b.appendChild(list('No longer valid (what they were based on changed)', p.stale));
    if (p.conflicts && p.conflicts.length) b.appendChild(list('Two current values; the later one is preferred', p.conflicts));
    w.appendChild(b);
  } else if (m.mode === 'ask') {
    const ev = p.evidence || [], abstain = !ev.length || /^I (don't|do not) know|^I can only look|^I'm not sure/.test(m.content);
    if (abstain) w.classList.add('abstain');
    const b = el('div', 'bubble', m.content); b.tabIndex = 0; b.onclick = () => openAnswer(m); b.onkeydown = (e) => { if (e.key === 'Enter') openAnswer(m); };
    const readOnly = (p.trace || []).some((t) => t.step === 'read_only');
    w.append(b, el('div', 'meta', readOnly ? 'Ask only reads memory. Use Tell to store, correct or forget something.' : ev.length ? `${ev.length} source(s). Click the answer to inspect.` : 'No supporting memory. Click for details.'));
  } else {
    const b = el('div', 'bubble', m.content); b.tabIndex = 0; b.onclick = () => openJob(m); b.onkeydown = (e) => { if (e.key === 'Enter') openJob(m); };
    const n = ((p.trace || []).filter((t) => t.step === 'tool')).length, blocked = ((p.trace || []).filter((t) => t.step === 'blocked')).length;
    w.append(b, el('div', 'meta', `${n} tool call(s)${blocked ? `, ${blocked} blocked by a safety check` : ''}. Click the reply to inspect.`));
  }
