  e.preventDefault(); const text = $('input').value.trim(), m = mode(); if (!text) return;
  $('input').value = ''; $('send').disabled = true; await submit(m, text); $('send').disabled = false; $('input').focus();
};

// ---- evidence drawer ---------------------------------------------------------------------------------------------
function drawer(title, build) { $('drawer-title').textContent = title; const b = $('drawer-body'); b.replaceChildren(); build(b); $('drawer').hidden = $('scrim').hidden = false; $('close').focus(); }
const closeDrawer = () => { $('drawer').hidden = $('scrim').hidden = true; };
$('close').onclick = $('scrim').onclick = closeDrawer;
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') { closeDrawer(); closeMenu(); } });
const steps = (b, trace, title = 'How it was found') => { b.appendChild(el('h4', null, title)); (trace || []).forEach((t) => b.appendChild(el('div', 'step', JSON.stringify(t)))); };
function openAnswer(m) {
  const p = m.payload || {}, ev = p.evidence || [];
  drawer('Answer details', (b) => {
    b.appendChild(el('h4', null, ev.length ? 'Evidence used' : 'No evidence cited'));
    if (!ev.length) b.appendChild(el('div', 'muted', 'Nothing stored supports a firm answer.'));
    ev.forEach((x) => { const d = el('div', 'ev', x.text); d.appendChild(el('small', null, 'message ' + x.message_id)); b.appendChild(d); });
