    if (!t.some((x) => x.step === 'tool')) b.appendChild(el('div', 'muted', 'No tools were called.'));
    const blocked = t.filter((x) => x.step === 'blocked');
    if (blocked.length) { b.appendChild(el('h4', null, 'Blocked by a safety check')); blocked.forEach((x) => b.appendChild(el('div', 'step', `${x.name}: ${x.reason}`))); }
