$('refresh').onclick = loadMemories;
async function loadMemories() {
  const tok = S.tok; $('facts').replaceChildren(el('div', 'empty dots', 'Loading'));
  try { const m = await call('GET', P('/memory')); if (tok !== S.tok) return; S.facts = m; renderMemories(); }
  catch (e) { if (tok === S.tok) $('facts').replaceChildren(el('div', 'errbox', 'Could not read this project\'s memory: ' + e.message)); }
}
function factCard(f, by) {
  const card = el('div', 'card' + (f.status === 'active' ? '' : ' old')), head = el('div', 'head');
  head.append(el('span', 'val', `${f.subject} · ${f.relation}: ${f.value}`), el('span', 'badge', f.kind.toLowerCase()),
    el('span', 'badge' + (f.attribution === 'other' ? ' other' : ''), f.attribution === 'other' ? 'said by someone else' : 'about you'));
  if (f.when_ts || f.when_date) head.append(el('span', 'badge', (f.when_ts || f.when_date).replace('T', ' ')));
  if (f.sensitive) head.append(el('span', 'badge bad', 'private'));
  if (f.status === 'superseded') head.append(el('span', 'badge history', 'replaced ' + day(f.ended_ts)));
  if (f.status === 'stale') head.append(el('span', 'badge history', 'no longer valid ' + day(f.ended_ts)));
  if (f.conflict_with && by[f.conflict_with] && by[f.conflict_with].status === 'active') head.append(el('span', 'badge bad', `conflicts with #${f.conflict_with}`));
  if (f.derived_from.length) head.append(el('span', 'badge', 'derived from ' + f.derived_from.map((i) => '#' + i).join(', ')));
  card.append(head, el('div', 'quote', `“${f.quote}”`), el('div', 'muted', `#${f.id} · from message ${f.first_message_id} · noted ${day(f.created_ts)} · ${f.evidence_count} source(s)`));
  return card;
}
function renderMemories() {
  const m = S.facts; if (!m) return;
  const box = $('facts'); box.replaceChildren(); const by = Object.fromEntries(m.facts.map((f) => [f.id, f]));
  $('counts').textContent = `${m.counts.active} current · ${m.counts.history} earlier · ${m.counts.sources} source(s)`;
  let rows = m.facts;
  if (S.filter === 'active') rows = rows.filter((f) => f.status === 'active');
  if (S.filter === 'timeline') rows = rows.filter((f) => f.is_head).sort((a, b) => (b.created_ts || '').localeCompare(a.created_ts || ''));
  if (!rows.length) box.appendChild(el('div', 'empty', m.counts.sources ? 'Nothing matches this view yet.' : 'Nothing is stored in this project yet. Tell me something on the Chat page.'));
  rows.forEach((f) => {
    const card = factCard(f, by);
    if (S.filter === 'timeline' && f.versions.length) {
      const hist = el('div', 'versions'); hist.appendChild(el('h4', null, 'Earlier versions'));
      f.versions.forEach((id) => { const v = by[id]; hist.appendChild(el('div', 'ver', `${v.value}  ·  noted ${day(v.created_ts)}${v.ended_ts ? `, replaced ${day(v.ended_ts)}` : ''}  ·  “${v.quote}”`)); });
      card.appendChild(hist);
    }
    box.appendChild(card);
  });
  const fb = $('forgets'); fb.replaceChildren();
  if (!m.forgets.length) fb.appendChild(el('div', 'empty', 'Nothing has been forgotten in this project.'));
  m.forgets.forEach((r) => { const d = el('div', 'card'), h = el('div', 'head');
    h.append(el('span', null, `${r.facts_removed} fact(s) and ${r.sources_removed} source(s) erased`), el('span', 'badge ' + (r.verified ? 'good' : 'bad'), r.verified ? 'verified' : `${r.problems} problem(s)`), el('span', 'muted', day(r.ts)));
    d.appendChild(h); fb.appendChild(d); });
}

