// Drives Edge through the DevTools protocol: functional checks plus screenshots in both themes.
import fs from 'fs';
import os from 'os';
import path from 'path';
import { spawn } from 'child_process';

const BASE = process.env.BASE, OUT = process.env.OUT, PORT = 9333;
const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'edge-'));
const proc = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--remote-debugging-port=${PORT}`, `--user-data-dir=${tmp}`, '--window-size=1280,900', 'about:blank'], { stdio: 'ignore' });
let ws, id = 0; const pending = new Map(), errors = [];
async function connect() {
  for (let i = 0; i < 30; i++) {
    try { const tabs = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json(); const page = tabs.find((t) => t.type === 'page'); if (page) { ws = new WebSocket(page.webSocketDebuggerUrl); await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; }); return; } } catch { /* browser still starting */ }
    await sleep(500);
  }
  throw new Error('browser did not start');
}
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0, 300)); return r.result.result.value; };
const shot = async (name) => { const r = await send('Page.captureScreenshot', { format: 'png' }); fs.writeFileSync(path.join(OUT, name + '.png'), Buffer.from(r.result.data, 'base64')); };
const wait = async (cond, ms = 15000) => { const t = Date.now(); while (Date.now() - t < ms) { if (await ev(cond)) return true; await sleep(250); } throw new Error('timeout waiting for: ' + cond); };
const view = (w, h) => send('Emulation.setDeviceMetricsOverride', { width: w, height: h, deviceScaleFactor: 1, mobile: w < 600 });
const results = [];
const check = (name, ok, extra = '') => { results.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? '  ' + extra : ''}`); };

await connect();
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } else if (m.method === 'Runtime.exceptionThrown' || (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error')) errors.push(JSON.stringify(m.params).slice(0, 200)); };
await send('Runtime.enable'); await send('Page.enable');
await view(1280, 900);

for (const theme of ['dark', 'light']) {
  await send('Page.navigate', { url: `${BASE}/?theme=${theme}` });
  await wait("document.querySelectorAll('#transcript .msg').length > 0");
  check(`[${theme}] page loads with the seeded conversation`, true);
  check(`[${theme}] theme applied`, (await ev('document.documentElement.dataset.theme')) === theme);
  check(`[${theme}] background token resolves`, (await ev("getComputedStyle(document.body).backgroundColor")) === (theme === 'dark' ? 'rgb(26, 29, 38)' : 'rgb(244, 245, 247)'));
  const font = await ev("getComputedStyle(document.querySelector('.msg.user .bubble')).fontFamily");
  check(`[${theme}] user bubble uses the serif token`, /Newsreader|Georgia/.test(font), font.slice(0, 40));
  check(`[${theme}] header is 60px`, (await ev("document.querySelector('.top').offsetHeight")) === 60);
  check(`[${theme}] rail is 260px`, (await ev("document.getElementById('rail').offsetWidth")) === 260 + 0 || (await ev("document.getElementById('rail').offsetWidth")) >= 259);
  await shot(`${theme}-1-chat`);
  // open the structured answer details from the last Ask
  await ev("[...document.querySelectorAll('.msg.bot .bubble[role=button]')].filter((b)=>b.closest('.msg').querySelector('.meta')).pop().click()");
  await wait("!document.getElementById('drawer').hidden");
  check(`[${theme}] answer drawer shows evidence cards`, (await ev("document.querySelectorAll('#drawer .evcard').length")) >= 1);
  check(`[${theme}] drawer shows the retrieval flow steps`, (await ev("document.querySelectorAll('#drawer .step').length")) >= 7);
  check(`[${theme}] drawer shows usage with a counting basis`, /Counted as/.test(await ev("document.getElementById('drawer-body').innerText")));
  check(`[${theme}] raw JSON is collapsed by default`, (await ev("[...document.querySelectorAll('#drawer details.raw')].every((d)=>!d.open)")) === true);
  check(`[${theme}] drawer has no raw JSON outside the optional section`, !/\{\s*"step"/.test(await ev("[...document.querySelectorAll('#drawer-body > :not(details)')].map((n)=>n.innerText).join(' ')")));
  await shot(`${theme}-2-answer-details`);
  // open an individual memory from the evidence
  await ev("document.querySelector('#drawer .evcard button').click()");
  await wait("document.getElementById('drawer-title').textContent.startsWith('Memory #')");
  check(`[${theme}] memory inspector opens from the evidence`, true);
  await shot(`${theme}-3-memory-inspector`);
  await ev("document.getElementById('close').click()");
  check(`[${theme}] Escape/close returns focus and hides the drawer`, await ev("document.getElementById('drawer').hidden"));
