let ws, id = 0; const pending = new Map(), errors = [];
async function connect() {
  for (let i = 0; i < 30; i++) {
    try { const tabs = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json(); const page = tabs.find((t) => t.type === 'page'); if (page) { ws = new WebSocket(page.webSocketDebuggerUrl); await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; }); return; } } catch { /* browser still starting */ }
    await sleep(500);
  }
  throw new Error('browser did not start');
}
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0, 300)); return r.result.result.value; };
