import fs from 'fs';
import os from 'os';
import path from 'path';
import { spawn } from 'child_process';
const BASE = process.env.BASE, OUT = process.env.OUT, PORT = 9334;
const EDGE = 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const proc = spawn(EDGE, ['--headless=new', '--disable-gpu', '--no-first-run', `--remote-debugging-port=${PORT}`, `--user-data-dir=${fs.mkdtempSync(path.join(os.tmpdir(), 'edge-'))}`, '--window-size=1280,900', 'about:blank'], { stdio: 'ignore' });
let ws, id = 0; const pending = new Map();
for (let i = 0; i < 30 && !ws; i++) { try { const tabs = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json(); const page = tabs.find((t) => t.type === 'page'); ws = new WebSocket(page.webSocketDebuggerUrl); await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; }); } catch { ws = null; await sleep(500); } }
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })).result.result.value;
const shot = async (name) => fs.writeFileSync(path.join(OUT, name + '.png'), Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'));
await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 800, deviceScaleFactor: 1, mobile: true });
await send('Page.navigate', { url: `${BASE}/?theme=light` }); await sleep(2500);
await shot('m-light-1-chat');
await ev("document.getElementById('rail-toggle').click()"); await sleep(800);
await shot('m-light-2-rail');
await ev("document.getElementById('rail-close').click()"); await sleep(600);
await ev("[...document.querySelectorAll('.msg.bot .bubble[role=button]')].filter((b)=>b.closest('.msg').querySelector('.meta')).pop().click()"); await sleep(700);
await shot('m-light-3-drawer');
await ev("document.getElementById('close').click()");
await ev("document.querySelector('[data-page=system]').click()"); await sleep(1500);
await shot('m-light-4-system');
proc.kill(); process.exit(0);

