.card .val { font: 17px/1.4 var(--serif); }
.badge { padding: 1px 10px; font-size: 12px; font-weight: 500; background: color-mix(in srgb, var(--raised) 70%, transparent); border-color: var(--line-strong); }
.badge.good { background: color-mix(in srgb, var(--good) 14%, transparent); border-color: color-mix(in srgb, var(--good) 45%, transparent); }
.badge.bad { background: var(--forget-bg); border-color: color-mix(in srgb, var(--forget) 50%, transparent); }
.badge.other { background: color-mix(in srgb, var(--planned) 14%, transparent); border-color: color-mix(in srgb, var(--planned) 45%, transparent); }
.badge.history { background: var(--hl-soft); border-color: color-mix(in srgb, var(--hl) 45%, transparent); }
.empty, .errbox { border-radius: 16px; padding: 26px; background: color-mix(in srgb, var(--surface) 55%, transparent); }
.errbox { background: var(--forget-bg); }
.tbl { border: 1px solid var(--line); border-radius: 14px; border-collapse: separate; border-spacing: 0; overflow: hidden; background: var(--surface); box-shadow: var(--elev-1); }
.tbl caption { padding: 0 2px 10px; }
.tbl th, .tbl td { padding: 11px 14px; }
.tbl tr:last-child td { border-bottom: 0; }
.sys { background: var(--surface); border: 1px solid var(--line); border-radius: 16px; padding: 16px 20px; box-shadow: var(--elev-1); }
h3 { font: 500 18px/1.2 var(--serif); }

/* ---- drawer, dialog, scrim ---- */
.scrim { background: var(--scrim); backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px); }
.scrim:not([hidden]) { animation: fade .2s var(--ease); }
.drawer { background: var(--panel), var(--surface); border-left: 1px solid var(--line-strong); box-shadow: var(--elev-2); padding: 22px; }
.drawer:not([hidden]) { animation: slideIn .28s var(--ease); }
.drawer-head strong { font: 500 20px/1.2 var(--serif); }
.drawer h4 { font-size: 11px; letter-spacing: .1em; }
.evcard { background: var(--panel), var(--sunken); border-radius: 15px; box-shadow: var(--elev-1); padding: 14px 16px; }
.evcard:hover { border-color: var(--line-strong); }
