.ink { border-radius: 13px; background: var(--ink-button); box-shadow: var(--elev-1), inset 0 1px 0 rgba(255, 255, 255, .16); }
.ink:hover:not(:disabled) { transform: translateY(-1px); box-shadow: var(--elev-2), inset 0 1px 0 rgba(255, 255, 255, .2); }
.ink:active:not(:disabled) { transform: none; }
#send { height: 40px; padding: 0 20px; }
.danger { border-radius: 12px; }
