/* ---- welcome ---- */
.welcome { position: relative; padding-top: 9vh; }
.welcome::before { content: ''; position: absolute; left: -50px; top: 3vh; width: 420px; height: 220px; background: radial-gradient(closest-side, var(--ring), transparent); filter: blur(34px); opacity: .6; z-index: -1; }
.welcome h1 { font: 500 38px/1.15 var(--serif); letter-spacing: -.01em; background: linear-gradient(115deg, var(--text) 30%, var(--hl)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.welcome p { font-size: 15.5px; line-height: 1.65; }

/* ---- memories, system, shared surfaces ---- */
.page.wide { padding-top: 34px; }
h2 { font: 500 24px/1.2 var(--serif); letter-spacing: -.01em; }
.chips { background: var(--sunken); border: 1px solid var(--line); border-radius: 12px; padding: 3px; gap: 2px; }
.chips button { border: 0; border-radius: 9px; padding: 4px 13px; color: var(--muted); font-weight: 500; }
.chips button:hover { color: var(--text); background: var(--hover); }
.chips button.on { background: var(--raised); color: var(--text); box-shadow: var(--elev-1), inset 0 0 0 1px var(--line); }
.filters-row input, .filters-row select, .world input, dialog input { background: var(--surface); border: 1px solid var(--line-strong); border-radius: 12px; padding: 9px 13px; }
.filters-row input:focus, .filters-row select:focus, .world input:focus, dialog input:focus { outline: 0; border-color: var(--hl); box-shadow: 0 0 0 4px var(--ring); }
.card { background: var(--panel), var(--surface); border-radius: 16px; padding: 15px 18px; box-shadow: var(--elev-1); animation: rise .24s var(--ease) both; }
.card:hover { border-color: var(--line-strong); transform: translateY(-1px); }
.card.old { background: var(--sunken); box-shadow: none; }
.card .val { font: 17px/1.4 var(--serif); }
.badge { padding: 1px 10px; font-size: 12px; font-weight: 500; background: color-mix(in srgb, var(--raised) 70%, transparent); border-color: var(--line-strong); }
.badge.good { background: color-mix(in srgb, var(--good) 14%, transparent); border-color: color-mix(in srgb, var(--good) 45%, transparent); }
.badge.bad { background: var(--forget-bg); border-color: color-mix(in srgb, var(--forget) 50%, transparent); }
.badge.other { background: color-mix(in srgb, var(--planned) 14%, transparent); border-color: color-mix(in srgb, var(--planned) 45%, transparent); }
.badge.history { background: var(--hl-soft); border-color: color-mix(in srgb, var(--hl) 45%, transparent); }
.empty, .errbox { border-radius: 16px; padding: 26px; background: color-mix(in srgb, var(--surface) 55%, transparent); }
.errbox { background: var(--forget-bg); }
.tbl { border: 1px solid var(--line); border-radius: 14px; border-collapse: separate; border-spacing: 0; overflow: hidden; background: var(--surface); box-shadow: var(--elev-1); }
.tbl caption { padding: 0 2px 10px; }
.tbl th, .tbl td { padding: 11px 14px; }
.tbl tr:last-child td { border-bottom: 0; }
.sys { background: var(--surface); border: 1px solid var(--line); border-radius: 16px; padding: 16px 20px; box-shadow: var(--elev-1); }
h3 { font: 500 18px/1.2 var(--serif); }

/* ---- drawer, dialog, scrim ---- */
.scrim { background: var(--scrim); backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px); }
.scrim:not([hidden]) { animation: fade .2s var(--ease); }
.drawer { background: var(--panel), var(--surface); border-left: 1px solid var(--line-strong); box-shadow: var(--elev-2); padding: 22px; }
.drawer:not([hidden]) { animation: slideIn .28s var(--ease); }
.drawer-head strong { font: 500 20px/1.2 var(--serif); }
.drawer h4 { font-size: 11px; letter-spacing: .1em; }
.evcard { background: var(--panel), var(--sunken); border-radius: 15px; box-shadow: var(--elev-1); padding: 14px 16px; }
.evcard:hover { border-color: var(--line-strong); }
.evquote { border-left: 2px solid var(--hl); border-radius: 0; }
.step .dot { background: var(--surface); box-shadow: 0 0 0 4px var(--hl-soft); }
.step.off .dot { box-shadow: none; }
details.raw summary { padding: 4px 0; }
details.raw pre { border-radius: 12px; }
dialog { border-radius: 20px; padding: 26px; box-shadow: var(--elev-2); background: var(--panel), var(--surface); }
dialog[open] { animation: pop .18s var(--ease); }
dialog::backdrop { backdrop-filter: blur(4px); }
.skip { border-radius: 10px; }

/* ---- narrow screens: same refinements, tighter ---- */
@media (max-width: 720px) {
  .mark::before { width: 20px; height: 20px; }
  .msg.bot { padding-left: 38px; }
  .msg.bot::before { width: 26px; height: 26px; border-radius: 9px; }
  .msg.user .bubble { max-width: 88%; }
  .transcript { padding: 22px 14px 8px; }
  .composer { padding: 6px 14px 16px; }
  .welcome h1 { font-size: 30px; }
  .modes label { padding: 6px 10px; }
  .top nav { padding: 3px; }
}
@media (prefers-reduced-motion: reduce) { .msg, .card, .menu, dialog[open], .drawer, .scrim { animation: none !important; } }

